   elif text[pos]=='{':out+='('+group()+')'
   elif text[pos]=='^':pos+=1;out+='**'+('('+group()+')')
   else:out+=text[pos];pos+=1
  assert stop is None,(text,stop)
  return out
 return parse_expr(walk(),local_dict=V,transformations=TRANS)
